Use the following JSON prompt, the ingredient list, the image of the product packaging, the image of the product consistency, and the description of the product consistency to generate the image,

the ingredients and the consistency description are attached at the bottom of the prompt.

{
"task": "Generate a high-end, minimalistic haircare ingredient explainer image using reference product photography and dynamic ingredient inputs",

"input_parameters": {
"reference_product_images": {
"description": "List of product reference images. If multiple products appear in the image (ex: 2-bottle routine), automatically isolate and use only ONE primary bottle (hero bottle) for dispensing in the scene.",
"type": "array",
"max_primary_products_used": 1
},

"ingredients": {
"description": "List of ingredient objects. System will auto-generate benefit text and icons if missing.",
"type": "array",
"structure": {
"name": "string",
"benefit_description": "string | optional | if empty system generates",
"icon_description": "string | optional | if empty system generates thin-line icon concept"
}
}
},

"scene_constraints": {
"composition_lock": true,
"composition_description": "Close-up lifestyle product shot featuring a human hand held palm-up at center-right of frame, ACTIVELY dispensing product from the reference bottle. The bottle is partially visible entering from the right edge of the frame and is clearly in-use, angled downward, pouring cream into the palm. Left side reserved for ingredient text and icons. Exact layout must remain consistent regardless of input product.",
"aspect_ratio": "1:1"
},

"scene_description": {
"camera_angle": "Eye-level close-up with slight top-down perspective focused on palm, dispensing action, and product texture",

"background": "Seamless matte white studio background with subtle warm undertones",

"lighting": {
"type": "High-key studio with carioca warmth",
"direction": "Soft diffused light from upper left",
"color_temperature": "Slightly golden daylight (warm sun-kissed tone, not yellow)",
"contrast": "Low contrast, airy, sunlit luxury",
"shadow_style": "Very soft natural contact shadows with gentle warmth"
}
},

"hand_and_product_rendering": {
"hand": {
"pose": "Palm open, fingers softly curved inward, clearly engaged in receiving product",
"interaction": "Hand and bottle interaction must feel natural and mid-action, as if captured during a real photoshoot",
"skin_finish": "Natural hydrated skin texture with subtle sunlit glow",
"nails": "Short to medium length, natural nude polish"
},

"cream_texture": {
"appearance": "Glossy dense white cream",
"behavior": "Mid-dispense moment — cream visibly flowing or freshly landed into the palm",
"finish": "Rich, moisturizing, premium haircare texture"
},

"reference_product_rules": {
"use_reference_bottle_design": true,
"preserve_label_and_branding": true,
"only_partial_bottle_visible": true,
"bottle_visibility": "Bottle enters frame from right edge only, cropped intentionally",
"orientation": "Angled downward, actively pouring into palm",
"interaction_priority": "Bottle must appear functionally in use, not posed or static",
"only_one_primary_product_allowed": true
}
},

"ingredient_processing_engine": {
"auto_generate_if_missing": {
"benefit_description": true,
"icon": true
},

"benefit_generation_rules": {
"tone": "Clinical luxury with carioca warmth",
"length": "Condensed, scan-friendly benefit (6–12 words)",
"style": "Confident, premium, effortless",
"focus": [
"Strength",
"Hydration",
"Frizz control",
"Softness",
"Volume",
"Repair",
"Healthy shine"
]
},

"icon_generation_rules": {
"style": "Minimal thin-line black outline icon",
"container": "Circular outline",
"visual_language": "Clinical beauty meets tropical softness",
"clarity": "Legible at small mobile sizes"
}
},

"graphic_layout_system": {
"icon_and_line_layout": {
"placement": "Icons placed around cream with thin straight connector lines pointing to the product dollop",
"line_style": "Thin black straight lines",
"icon_numbering": "Automatic numbering based on ingredient order"
},

"text_layout": {
"placement": "Left side vertical stack",
"alignment": "Left aligned",
"font_style": "Modern premium sans-serif",
"color": "Black text",
"hierarchy": {
"ingredient_name": "Semi-bold",
"benefit_text": "Regular weight"
}
}
},

"text_output_generation": {
"format_per_ingredient": {
"line_1": "Ingredient Name",
"line_2": "Condensed benefit statement"
},

"optimization_rules": [
"Avoid scientific over-explanation",
"Avoid generic marketing fluff",
"Prioritize clarity and warmth",
"Must feel editorial, premium, and sunlit"
]
},

"brand_aesthetic": {
"overall_feel": "Clean clinical luxury with carioca sun warmth",
"emotional_response": [
"Trust",
"Ease",
"Glow",
"Effortless beauty"
]
},

"post_processing": {
"skin_retouch": "Natural only, preserve realism",
"color_grade": "Neutral whites with subtle golden warmth",
"clarity": "High detail on cream texture, soft falloff elsewhere"
},

"output_requirements": {
"resolution": "4K square minimum",
"usage": [
"Amazon A+",
"DTC PDP ingredient education",
"Paid social static ads"
]
}
}

INGREDIENTS: Aloe Vera, Prodew 500 Amino Acids, Hydrolyzed Keratin, Castor Oil
PRODUCT_CONSISTENCY: A light, pastel aquamarine gel-cream with a smooth, glossy, and slightly wet texture. It exhibits a medium-to-high viscosity, holding its squiggly, piled shape and retaining the visible ridges from being dispensed without immediately flattening or running. The consistency appears thick and creamy yet slightly translucent at the thinner, trailing edges, suggesting a pliable, easily spreadable formula that bridges the gap between a dense lotion and a soft, structured gel.

